import 'package:get/get.dart';import '../../../core/models/account.dart';import '../../../core/routes/app_routes.dart';import '../../../core/services/api_service.dart';import '../../../core/services/socket_service.dart';import '../../../core/services/notification_service.dart';import '../../../core/services/storage_service.dart';
class AuthController extends GetxController {
  final selectedRole='user'.obs; final loading=false.obs; final account=Rxn<Account>(); ApiService get api=>Get.find(); StorageService get storage=>Get.find(); SocketService get socket=>Get.find();
  Future<void> login(String email,String password) async {await _guard(()=>api.post('/auth/login',data:{'email':email.trim(),'password':password,'role':selectedRole.value}),route:true);}
  Future<void> registerUser({required String name,required String email,required String phone,required String password}) async {await _guard(()=>api.post('/auth/register/user',data:{'name':name,'email':email,'phone':phone,'password':password}),route:true);}
  Future<void> registerDriver({required String name,required String email,required String phone,required String password,required String license,required String make,required String model,required String color,required String plate,required String vehicleType}) async {await _guard(()=>api.post('/auth/register/driver',data:{'name':name,'email':email,'phone':phone,'password':password,'licenseNumber':license,'vehicle':{'make':make,'model':model,'color':color,'plateNumber':plate,'type':vehicleType}}),route:true);}
  Future<void> _guard(Future<Map<String,dynamic>> Function() fn,{bool route=false})async{try{loading.value=true;final r=await fn();if(r['token']!=null){final a=Account.fromJson(Map<String,dynamic>.from(r['account']));account.value=a;await storage.saveSession(r['token'],a.role);socket.connect();Get.find<NotificationService>().registerForPush();if(route)Get.offAllNamed(a.role=='driver'?AppRoutes.driverHome:AppRoutes.userHome);} }catch(e){Get.snackbar('Request failed',_message(e));}finally{loading.value=false;}}
  Future<void> refreshMe() async {try{final r=await api.get('/auth/me');account.value=Account.fromJson(Map<String,dynamic>.from(r['account']));}catch(_){}}
  Future<void> restore() async {if(storage.token==null)return;try{final r=await api.get('/auth/me');final a=Account.fromJson(Map<String,dynamic>.from(r['account']));account.value=a;socket.connect();Get.find<NotificationService>().registerForPush();Get.offAllNamed(a.role=='driver'?AppRoutes.driverHome:AppRoutes.userHome);}catch(_){await logout();}}
  Future<void> logout() async {socket.disconnect();await storage.clear();account.value=null;Get.offAllNamed(AppRoutes.role);}
  String _message(Object e)=>e.toString().replaceFirst('DioException','Network error');
}
